parameters.text:
=
* empresa_nome: {{ $json.empresa_nome }}
* empresa_site: {{ $json.empresa_site }}
* lista_empresas: {{ JSON.stringify($('Busca dados do banco').first().json.lista_empresas) }}

parameters.jsCode:
// Roda uma vez por lead novo: junta o lead original com o que a IA decidiu.
// O lead original é achado pela POSIÇÃO (o 1º que foi pra IA é o 1º que volta),
// porque o "Verifica duplicatas" não informa a ligação item a item e o n8n
// dá erro a partir do 2º lead quando se usa "o item ligado".
const leads = $('Verifica duplicatas').all();
const lead = leads[$itemIndex]?.json;
if (!lead || !lead.nome) {
  throw new Error(`Não achei o lead da posição ${$itemIndex} pra juntar com a resposta da IA.`);
}
const ia = $json.output || {};

// A IA responde a situação em texto; aqui traduz pro código que o banco usa.
const mapa = {
  'cliente': 'cliente',
  'em negociacao': 'em_negociacao',
  'em negociação': 'em_negociacao',
  'ja no crm': 'em_andamento',
  'já no crm': 'em_andamento',
};

const situacao = String(ia.situacao || '').trim().toLowerCase();
const achou = ia.empresa_correspondente || null;

return {
  json: {
    ...lead,
    cliente_match: ia.match || 'nenhuma',
    cliente_categoria_ia: achou ? (mapa[situacao] || null) : null,
    cliente_nome_ia: achou,
    cliente_motivo_ia: ia.motivo || null,
  },
};

const resultado = $items('Busca dados do banco')[0]?.json || {};

const normLinkedin = (url) =>
  url ? url.trim().toLowerCase().replace(/\/$/, '') : '';

const linkedinExistentes = new Set(
  (resultado.linkedin_urls_existentes || [])
    .map(normLinkedin)
    .filter(Boolean)
);

const results = $items('Prospecting Contacts')[0].json.results || [];

const seen = new Set();

return results
  .map(lead => {
    const linkedin = normLinkedin(lead.socialLinks?.linkedin);
    if (!linkedin) return null;
    if (linkedinExistentes.has(linkedin)) return null;
    if (seen.has(linkedin)) return null; // repetido dentro da própria busca
    seen.add(linkedin);

    const nome = [lead.firstName, lead.lastName]
      .filter(Boolean)
      .join(' ')
      .trim();
    if (!nome) return null;

    return {
      json: {
        nome,
        cargo: lead.jobTitle?.title ?? null,
        linkedin_url: lead.socialLinks?.linkedin ?? null,
        empresa_nome: lead.company?.name ?? null,
        empresa_site: lead.company?.domain ?? null,
        empresa_setor: lead.jobTitle?.departments?.[0] ?? null,
        origem: 'lusha_n8n',
        lusha_contact_id: lead.id ?? null,
        id_company_lusha: lead.company.id ?? null
      },
    };
  })
  .filter(Boolean);

